"use client";

import React, { useRef, useEffect } from "react";
import { useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";

export type AIVoiceOrbState = "idle" | "listening" | "thinking" | "speaking";
export type AIVoiceOrbTheme = "aurora" | "monochrome" | "chromatic";

export interface AIVoiceOrbProps {
  /** Active interactive state. Default: "idle" */
  state?: AIVoiceOrbState;
  /** Diameter of the orb in pixels. Default: 240 */
  size?: number;
  /** Color theme. Default: "chromatic" */
  theme?: AIVoiceOrbTheme;
  /** Simulated or real audio input level (0 to 1) */
  audioLevel?: number;
  /** Custom click handler */
  onClick?: () => void;
  className?: string;
}

const THEME_PALETTES: Record<
  AIVoiceOrbTheme,
  { c1: string; c2: string; c3: string; c4: string }
> = {
  chromatic: {
    c1: "rgba(99, 102, 241, 0.8)", // indigo
    c2: "rgba(236, 72, 153, 0.7)", // pink
    c3: "rgba(56, 189, 248, 0.8)", // sky
    c4: "rgba(251, 146, 60, 0.7)", // orange
  },
  aurora: {
    c1: "rgba(16, 185, 129, 0.8)", // emerald
    c2: "rgba(6, 182, 212, 0.75)", // cyan
    c3: "rgba(139, 92, 246, 0.75)", // purple
    c4: "rgba(52, 211, 153, 0.6)", // mint
  },
  monochrome: {
    c1: "rgba(255, 255, 255, 0.85)",
    c2: "rgba(200, 200, 210, 0.6)",
    c3: "rgba(140, 140, 150, 0.7)",
    c4: "rgba(90, 90, 100, 0.5)",
  },
};

export function AIVoiceOrb({
  state = "idle",
  size = 240,
  theme = "chromatic",
  audioLevel = 0,
  onClick,
  className,
}: AIVoiceOrbProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const reduceMotion = useReducedMotion();
  const stateRef = useRef(state);
  const audioLevelRef = useRef(audioLevel);
  const themeRef = useRef(theme);

  useEffect(() => {
    stateRef.current = state;
    audioLevelRef.current = audioLevel;
    themeRef.current = theme;
  }, [state, audioLevel, theme]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let animId: number;
    let t = 0;

    const dpr = typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1;
    canvas.width = size * dpr;
    canvas.height = size * dpr;
    ctx.scale(dpr, dpr);

    const render = () => {
      const currentState = stateRef.current;
      const currentAudio = audioLevelRef.current;
      const currentPalette = THEME_PALETTES[themeRef.current] || THEME_PALETTES.chromatic;

      // Speed configuration based on state
      let speed = 0.02;
      let amplitudeMultiplier = 1;

      if (currentState === "thinking") {
        speed = 0.07;
        amplitudeMultiplier = 1.3;
      } else if (currentState === "listening") {
        speed = 0.03 + currentAudio * 0.04;
        amplitudeMultiplier = 1 + currentAudio * 2.2;
      } else if (currentState === "speaking") {
        speed = 0.05 + Math.sin(t * 3) * 0.02;
        amplitudeMultiplier = 1.6 + Math.sin(t * 4) * 0.8;
      } else {
        // idle
        speed = 0.015;
        amplitudeMultiplier = 0.9 + Math.sin(t * 1.5) * 0.15;
      }

      if (reduceMotion) {
        speed = 0;
        amplitudeMultiplier = 1;
      }

      t += speed;

      ctx.clearRect(0, 0, size, size);

      const cx = size / 2;
      const cy = size / 2;
      const baseRadius = size * 0.35;

      // Outer soft glow halo
      const haloGrad = ctx.createRadialGradient(cx, cy, baseRadius * 0.4, cx, cy, baseRadius * 1.5);
      haloGrad.addColorStop(0, currentPalette.c1.replace("0.8", "0.2"));
      haloGrad.addColorStop(0.6, currentPalette.c2.replace("0.7", "0.1"));
      haloGrad.addColorStop(1, "transparent");
      ctx.fillStyle = haloGrad;
      ctx.beginPath();
      ctx.arc(cx, cy, baseRadius * 1.45, 0, Math.PI * 2);
      ctx.fill();

      // Draw multi-layer organic harmonic blobs
      ctx.globalCompositeOperation = "screen";

      const layers = [
        { color: currentPalette.c1, angleOffset: 0, freq: 3, amp: 14 * amplitudeMultiplier },
        { color: currentPalette.c2, angleOffset: 2.1, freq: 4, amp: 18 * amplitudeMultiplier },
        { color: currentPalette.c3, angleOffset: 4.2, freq: 5, amp: 12 * amplitudeMultiplier },
        { color: currentPalette.c4, angleOffset: 1.0, freq: 3, amp: 16 * amplitudeMultiplier },
      ];

      for (const layer of layers) {
        ctx.beginPath();
        const points = 60;
        for (let i = 0; i <= points; i++) {
          const angle = (i / points) * Math.PI * 2;
          const wobble =
            Math.sin(angle * layer.freq + t + layer.angleOffset) * layer.amp +
            Math.cos(angle * 2 - t * 1.5) * (layer.amp * 0.5);
          const r = baseRadius + wobble;
          const x = cx + Math.cos(angle) * r;
          const y = cy + Math.sin(angle) * r;

          if (i === 0) {
            ctx.moveTo(x, y);
          } else {
            ctx.lineTo(x, y);
          }
        }
        ctx.closePath();

        const grad = ctx.createRadialGradient(
          cx + Math.cos(t + layer.angleOffset) * 20,
          cy + Math.sin(t + layer.angleOffset) * 20,
          0,
          cx,
          cy,
          baseRadius * 1.2
        );
        grad.addColorStop(0, layer.color);
        grad.addColorStop(0.7, layer.color.replace(/0\.\d+\)/, "0.4)"));
        grad.addColorStop(1, "transparent");

        ctx.fillStyle = grad;
        ctx.fill();
      }

      // Center Core Specular Brightness
      ctx.beginPath();
      const coreGrad = ctx.createRadialGradient(
        cx + Math.sin(t * 2) * 8,
        cy + Math.cos(t * 2) * 8,
        0,
        cx,
        cy,
        baseRadius * 0.6
      );
      coreGrad.addColorStop(0, "rgba(255, 255, 255, 0.85)");
      coreGrad.addColorStop(0.4, "rgba(255, 255, 255, 0.4)");
      coreGrad.addColorStop(1, "transparent");
      ctx.fillStyle = coreGrad;
      ctx.arc(cx, cy, baseRadius * 0.6, 0, Math.PI * 2);
      ctx.fill();

      ctx.globalCompositeOperation = "source-over";

      animId = requestAnimationFrame(render);
    };

    render();

    return () => {
      cancelAnimationFrame(animId);
    };
  }, [size, reduceMotion]);

  return (
    <div
      onClick={onClick}
      style={{ width: size, height: size }}
      className={cn(
        "relative flex items-center justify-center select-none cursor-pointer transition-transform active:scale-95",
        className
      )}
    >
      <canvas
        ref={canvasRef}
        style={{ width: size, height: size }}
        className="block rounded-full"
      />
    </div>
  );
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export async function copyToClipboard(text: string): Promise<boolean> {
  if (typeof window === "undefined") return false;

  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }

    const textArea = document.createElement("textarea");
    textArea.value = text;
    textArea.style.position = "fixed";
    textArea.style.left = "-999999px";
    textArea.style.top = "-999999px";
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    const succeeded = document.execCommand("copy");
    textArea.remove();
    return succeeded;
  } catch {
    return false;
  }
}

"use client";

import React, { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";

export interface AccordionItem {
  id: string;
  title: string;
  subtitle?: string;
  content: React.ReactNode;
}

export interface AccordionProps {
  /** Array of collapsible items */
  items?: AccordionItem[];
  /** Allow multiple items to stay open simultaneously */
  allowMultiple?: boolean;
  /** Default open item IDs */
  defaultOpenIds?: string[];
  /** Additional container class names */
  className?: string;
}

const DEFAULT_ITEMS: AccordionItem[] = [
  {
    id: "item-1",
    title: "How do I install BoseUI components?",
    subtitle: "CLI & Manual Copy",
    content:
      "Run npx shadcn@latest add https://boseui.site/r/<slug>.json in your project terminal, or copy the TypeScript code directly from any component page.",
  },
  {
    id: "item-2",
    title: "Can I customize the Tailwind styles and animations?",
    subtitle: "100% Source Ownership",
    content:
      "Yes. Because the source file lives directly inside your src/components/ui/ folder, you can edit every Tailwind class, Framer Motion spring parameter, or TypeScript prop.",
  },
  {
    id: "item-3",
    title: "Does it support Light Mode, Dark Mode, and Reduced Motion?",
    subtitle: "Built-in Accessibility",
    content:
      "Every component is designed for high-contrast Light and Dark themes and automatically respects system prefers-reduced-motion settings.",
  },
];

export function Accordion({
  items = DEFAULT_ITEMS,
  allowMultiple = false,
  defaultOpenIds = ["item-1"],
  className,
}: AccordionProps) {
  const shouldReduceMotion = useReducedMotion();
  const [openIds, setOpenIds] = useState<string[]>(defaultOpenIds);

  const toggleItem = (id: string) => {
    setOpenIds((prev) => {
      const isOpen = prev.includes(id);
      if (allowMultiple) {
        return isOpen ? prev.filter((i) => i !== id) : [...prev, id];
      }
      return isOpen ? [] : [id];
    });
  };

  return (
    <div
      className={cn(
        "w-full max-w-md divide-y divide-neutral-200 overflow-hidden rounded-2xl border border-neutral-200 bg-white dark:divide-[#1F1F1F] dark:border-[#222222] dark:bg-[#0A0A0A]",
        className
      )}
    >
      {items.map((item) => {
        const isOpen = openIds.includes(item.id);
        return (
          <div key={item.id} className="flex flex-col">
            <button
              type="button"
              aria-expanded={isOpen}
              onClick={() => toggleItem(item.id)}
              className="flex w-full cursor-pointer items-center justify-between gap-4 px-5 py-4 text-left transition-colors hover:bg-neutral-50 dark:hover:bg-[#111111]"
            >
              <div className="min-w-0">
                <div className="text-xs font-semibold text-black dark:text-white sm:text-sm">
                  {item.title}
                </div>
                {item.subtitle && (
                  <div className="mt-0.5 font-mono text-[10px] uppercase tracking-wider text-neutral-400">
                    {item.subtitle}
                  </div>
                )}
              </div>

              <motion.span
                animate={{ rotate: isOpen ? 180 : 0 }}
                transition={
                  shouldReduceMotion
                    ? { duration: 0 }
                    : { type: "spring", stiffness: 360, damping: 26 }
                }
                className="flex h-6 w-6 shrink-0 items-center justify-center rounded-md border border-neutral-200 text-neutral-500 dark:border-[#262626] dark:text-neutral-400"
              >
                <ChevronDown className="h-3.5 w-3.5" />
              </motion.span>
            </button>

            <AnimatePresence initial={false}>
              {isOpen && (
                <motion.div
                  initial={
                    shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }
                  }
                  animate={
                    shouldReduceMotion
                      ? { opacity: 1 }
                      : { height: "auto", opacity: 1 }
                  }
                  exit={
                    shouldReduceMotion ? { opacity: 0 } : { height: 0, opacity: 0 }
                  }
                  transition={{
                    duration: shouldReduceMotion ? 0 : 0.22,
                    ease: [0.22, 1, 0.36, 1],
                  }}
                  className="overflow-hidden"
                >
                  <div className="px-5 pb-4 text-xs leading-relaxed text-neutral-600 dark:text-neutral-400">
                    {item.content}
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        );
      })}
    </div>
  );
}

export default Accordion;

