export function AppleContextMenu({
  groups = DEFAULT_GROUPS,
  triggerLabel = "Actions Menu",
  defaultOpen = false,
  onSelect,
  className,
}: AppleContextMenuProps) {
  const shouldReduceMotion = useReducedMotion() ?? false;
  const containerRef = useRef<HTMLDivElement>(null);

  const [open, setOpen] = useState(defaultOpen);
  const [lastAction, setLastAction] = useState<string | null>(null);

  useEffect(() => {
    if (!open) return;
    const handleOutside = (e: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(e.target as Node)
      ) {
        setOpen(false);
      }
    };
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", handleOutside);
    window.addEventListener("keydown", handleEscape);
    return () => {
      document.removeEventListener("mousedown", handleOutside);
      window.removeEventListener("keydown", handleEscape);
    };
  }, [open]);

  const handleSelect = (item: ContextMenuItem) => {
    item.onSelect?.();
    onSelect?.(item);
    setLastAction(item.label);
    setOpen(false);
  };

  return (
    <div
      ref={containerRef}
      onContextMenu={(e) => {
        e.preventDefault();
        setOpen(true);
      }}
      className={cn("relative inline-flex flex-col items-center", className)}
    >
      {/* Trigger Bar */}
      <div className="flex items-center gap-2.5">
        <button
          type="button"
          aria-haspopup="menu"
          aria-expanded={open}
          onClick={() => setOpen((v) => !v)}
          className={cn(
            "inline-flex h-10 items-center gap-2 rounded-2xl border px-4 text-xs font-semibold shadow-2xs transition-all active:scale-95",
            open
              ? "border-neutral-900 bg-neutral-900 text-white dark:border-white dark:bg-white dark:text-black"
