];

const PALETTE_PRESETS: Record<string, string[]> = {
  Borealis: ["#10B981", "#06B6D4", "#8B5CF6", "#3B82F6"],
  Sonoma: ["#EC4899", "#8B5CF6", "#06B6D4", "#F59E0B"],
