  opacity = 0.85,
  variant = "day",
  children,
  className,
}: CloudsDriftProps) {
  const [activeVariant, setActiveVariant] = useState<SkyVariant>(variant);

  useEffect(() => {
    setActiveVariant(variant);
  }, [variant]);

  const theme = SKY_THEMES[activeVariant] ?? SKY_THEMES.day;
  const ActiveIcon = theme.icon;

  const baseDuration = Math.max(8, 36 / Math.max(0.2, speed));

  const layers: {
    id: string;
    tier: LayerTier;
    duration: number;
    top: string;
    scale: number;
    alpha: number;
    zIndex: number;
  }[] = [
    {
      id: "far",
      tier: "far",
      duration: baseDuration * 1.85,
      top: "6%",
      scale: 0.75,
      alpha: 0.58 * opacity,
      zIndex: 1,
    },
    {
      id: "mid",
      tier: "mid",
      duration: baseDuration * 1.25,
      top: "26%",
      scale: 0.98,
      alpha: 0.82 * opacity,
      zIndex: 2,
    },
    {
      id: "near",
      tier: "near",
      duration: baseDuration * 0.82,
      top: "46%",
      scale: 1.25,
      alpha: 0.98 * opacity,
      zIndex: 3,
    },
  ];

  return (
    <div
      data-fullscreen-scroll
