interface PetalParticle {
  x: number;
  y: number;
  depth: number;
  /** 0 = distant small, 1 = crisp mid-ground, 2 = foreground soft bokeh */
  plane: 0 | 1 | 2;
  size: number;
  yaw: number;
  pitch: number;
  roll: number;
  yawSpeed: number;
  pitchSpeed: number;
  rollSpeed: number;
  glidePhase: number;
  glideFreq: number;
  glideSpan: number;
  colorIndex: number;
}

const VARIANT_PALETTES: Record<
  PetalVariant,
  {
    label: string;
    bgTop: string;
    bgMid: string;
    bgBottom: string;
    sunbeam: string;
    colors: [string, string, string][];
  }
> = {
