      ["#FDF2F8", "#F9A8D4", "#EC4899"],
      ["#FFE4E6", "#FDA4AF", "#FB7185"],
      ["#FFFFFF", "#FCE7F3", "#F43F5E"],
    ],
  },
  autumn: {
