    )}
    {page.title && (
      <h2 className="text-4xl sm:text-6xl font-extrabold text-white tracking-tight leading-tight">
        {page.title}
      </h2>
    )}
    {page.description && (
      <p className="mt-4 text-base sm:text-lg text-slate-400 max-w-xl">
        {page.description}
      </p>
    )}
  </div>
);

